    except UnicodeEncodeError:
        raise ValueError("Cannot encode payload text to bytes")

    # Read Excel file
    try:
        df = pd.read_excel(io.BytesIO(excel_bytes), sheet_name=0, header=None)
    except Exception as e:
        raise ValueError(f"Failed to parse Excel data: {e}")

    # Find the header row containing 'Date' and 'Price'
    date_col = None
    price_col = None
    header_row = None

    for row_idx in range(min(20, len(df))):
        for col_idx in range(min(20, len(df.columns))):
            cell_value = str(df.iloc[row_idx, col_idx]).strip().lower()
            if 'date' in cell_value:
                date_col = col_idx
                header_row = row_idx
            if 'price' in cell_value or 'cushing' in cell_value or 'spot' in cell_value:
                price_col = col_idx
                header_row = row_idx if header_row is None else header_row

    if date_col is None or price_col is None:
        raise ValueError("Could not find Date and Price columns in Excel file")

    # Extract data starting from header_row + 1
    data_start = header_row + 1
    dates = []
    prices = []

    for idx in range(data_start, len(df)):
        date_val = df.iloc[idx, date_col]
        price_val = df.iloc[idx, price_col]

        # Skip empty rows
        if pd.isna(date_val) or pd.isna(price_val):
            continue

        # Parse date
        try:
            if isinstance(date_val, datetime.datetime):
                d = date_val.date()
            elif isinstance(date_val, datetime.date):
                d = date_val
            elif isinstance(date_val, str):
                d = pd.to_datetime(date_val).date()
            else:
                d = pd.to_datetime(str(date_val)).date()
        except Exception:
            continue

        # Parse price
        try:
            p = float(price_val)
        except (ValueError, TypeError):
            continue

        dates.append(d)
        prices.append(p)

    if not dates:
        raise ValueError("No valid date/price pairs found in Excel data")

    # Create DataFrame
    data_df = pd.DataFrame({'date': dates, 'price': prices})

    # Define periods
    period_2025_start = datetime.date(2025, 1, 1)
    period_2025_end = datetime.date(2025, 6, 30)
    period_2026_start = datetime.date(2026, 1, 1)
    period_2026_end = datetime.date(2026, 6, 30)

    # Filter and calculate averages
    mask_2025 = (data_df['date'] >= period_2025_start) & (data_df['date'] <= period_2025_end)
    prices_2025 = data_df.loc[mask_2025, 'price']

    mask_2026 = (data_df['date'] >= period_2026_start) & (data_df['date'] <= period_2026_end)
